import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.BuUvxvtQ.js";const m=JSON.parse('{"title":"FAQ & Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/faq.md","filePath":"web-app/faq.md"}'),s={name:"web-app/faq.md"};function i(n,e,h,l,c,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; Troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to &quot;FAQ &amp; Troubleshooting&quot;">​</a></h1><p>Common questions and fixes for Sky Style.</p><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><h3 id="my-recommendation-doesn-t-mention-my-closet-items" tabindex="-1">My recommendation doesn&#39;t mention my closet items <a class="header-anchor" href="#my-recommendation-doesn-t-mention-my-closet-items" aria-label="Permalink to &quot;My recommendation doesn&#39;t mention my closet items&quot;">​</a></h3><p>The AI uses your closet when the closet panel is engaged on the dashboard. Make sure:</p><ol><li>You&#39;ve added items on the <strong>Closet</strong> page (<code>/closet</code>).</li><li>The closet is active for the recommendation (open the closet panel on the dashboard before generating).</li><li>You haven&#39;t hit your daily <strong>closet usage</strong> limit (4/day on Free).</li></ol><h3 id="the-recommendation-says-the-wrong-temperature-unit" tabindex="-1">The recommendation says the wrong temperature unit <a class="header-anchor" href="#the-recommendation-says-the-wrong-temperature-unit" aria-label="Permalink to &quot;The recommendation says the wrong temperature unit&quot;">​</a></h3><p>Units are controlled by your account&#39;s <strong>unit preference</strong> (metric or imperial), set in <a href="./settings.html#units">Settings → Units</a>. Changing it updates both the dashboard and the public API. If it hasn&#39;t updated, refresh the page after saving.</p><h3 id="i-got-a-502-error" tabindex="-1">I got a 502 error <a class="header-anchor" href="#i-got-a-502-error" aria-label="Permalink to &quot;I got a 502 error&quot;">​</a></h3><p>A <code>502 Bad Gateway</code> means the upstream weather provider or AI backend was unavailable. This is transient — wait 2–5 seconds and retry. If it persists, check the <a href="https://status.coolmanyt.com/" target="_blank" rel="noreferrer">COOLman service status page</a>.</p><h3 id="the-ai-model-isn-t-the-one-i-expected" tabindex="-1">The AI model isn&#39;t the one I expected <a class="header-anchor" href="#the-ai-model-isn-t-the-one-i-expected" aria-label="Permalink to &quot;The AI model isn&#39;t the one I expected&quot;">​</a></h3><p>Sky Style picks the first <strong>available</strong> model in your plan&#39;s priority list (see <a href="./how-it-works.html#ai-models">How It Works → AI models</a>). If a provider&#39;s key isn&#39;t configured server-side, its models are skipped. To force a specific provider, Pro/Dev users can use <a href="./dashboard.html#bring-your-own-key-pro-dev">BYOK</a> to supply their own key.</p><h2 id="usage-limits" tabindex="-1">Usage &amp; limits <a class="header-anchor" href="#usage-limits" aria-label="Permalink to &quot;Usage &amp; limits&quot;">​</a></h2><h3 id="i-hit-my-daily-limit-—-when-does-it-reset" tabindex="-1">I hit my daily limit — when does it reset? <a class="header-anchor" href="#i-hit-my-daily-limit-—-when-does-it-reset" aria-label="Permalink to &quot;I hit my daily limit — when does it reset?&quot;">​</a></h3><p>All daily counters reset at <strong>midnight UTC</strong>. The dashboard shows your current usage against each limit.</p><h3 id="what-counts-as-a-model-switch" tabindex="-1">What counts as a &quot;model switch&quot;? <a class="header-anchor" href="#what-counts-as-a-model-switch" aria-label="Permalink to &quot;What counts as a &quot;model switch&quot;?&quot;">​</a></h3><p>Changing which AI model generates your recommendation counts as a <strong>model switch</strong> — a separate counter from AI uses (2/day on Free, unlimited on Pro/Dev). See <a href="./how-it-works.html#usage-limits">Usage limits</a>.</p><h3 id="why-is-my-follow-up-not-working" tabindex="-1">Why is my follow-up not working? <a class="header-anchor" href="#why-is-my-follow-up-not-working" aria-label="Permalink to &quot;Why is my follow-up not working?&quot;">​</a></h3><p>Follow-ups require an existing recommendation to refine. If you&#39;re in <strong>Chat mode</strong>, follow-ups append below; in <strong>Replace mode</strong>, they overwrite the current outfit. Check your <a href="./settings.html#dashboard-behaviour">follow-up mode</a> in Settings.</p><h2 id="account-security" tabindex="-1">Account &amp; security <a class="header-anchor" href="#account-security" aria-label="Permalink to &quot;Account &amp; security&quot;">​</a></h2><h3 id="i-lost-my-2fa-device" tabindex="-1">I lost my 2FA device <a class="header-anchor" href="#i-lost-my-2fa-device" aria-label="Permalink to &quot;I lost my 2FA device&quot;">​</a></h3><p>Use one of your <strong>recovery codes</strong> (saved when you enabled 2FA) to sign in. If you&#39;ve lost those too, contact support via the <a href="./account-and-support.html#feedback">Feedback</a> page — a developer can reset 2FA after verifying your identity.</p><div class="warning custom-block"><p class="custom-block-title">Recovery codes are shown once</p><p>Recovery codes are displayed only at setup. Download <code>skystyle-recovery-codes.txt</code> and store it safely. You can <a href="./security-and-privacy.html#two-factor-authentication-2fa">regenerate</a> them anytime (which invalidates the old set).</p></div><h3 id="how-do-i-delete-my-account" tabindex="-1">How do I delete my account? <a class="header-anchor" href="#how-do-i-delete-my-account" aria-label="Permalink to &quot;How do I delete my account?&quot;">​</a></h3><p>Go to <strong>Settings → Privacy Hub</strong> (or the Account page) and request deletion. It&#39;s a <strong>human-reviewed process</strong> — a developer actions it within 7 days. You can cancel anytime before then. See <a href="./security-and-privacy.html#account-deletion">Privacy Hub → Account deletion</a>.</p><h3 id="can-i-export-my-data" tabindex="-1">Can I export my data? <a class="header-anchor" href="#can-i-export-my-data" aria-label="Permalink to &quot;Can I export my data?&quot;">​</a></h3><p>Yes — the Privacy Hub offers a <strong>JSON export</strong> of your profile, settings, closet, usage, feedback, and security logs. Non-Dev accounts are limited to one export every <strong>12 hours</strong>. See <a href="./security-and-privacy.html#data-export">Privacy Hub → Data export</a>.</p><h2 id="api-keys-credits" tabindex="-1">API keys &amp; credits <a class="header-anchor" href="#api-keys-credits" aria-label="Permalink to &quot;API keys &amp; credits&quot;">​</a></h2><h3 id="i-can-t-create-more-api-keys" tabindex="-1">I can&#39;t create more API keys <a class="header-anchor" href="#i-can-t-create-more-api-keys" aria-label="Permalink to &quot;I can&#39;t create more API keys&quot;">​</a></h3><p>Each plan has a limit on <strong>active</strong> (non-revoked) keys: Free 3, Pro 20, Dev unlimited. Revoke a key you no longer need to free up a slot. See <a href="./api-dashboard.html#active-key-limits">API Dashboard</a>.</p><h3 id="my-api-key-has-no-credits" tabindex="-1">My API key has no credits <a class="header-anchor" href="#my-api-key-has-no-credits" aria-label="Permalink to &quot;My API key has no credits&quot;">​</a></h3><p>Each key starts with 50 API Credit. When it&#39;s empty, Sky Style uses one available <strong>App Credit</strong> as a fallback and returns an <code>X-Credit-Warning</code> header. To top up a key, allocate <code>$1.00 → 50 API Credit</code> on the <a href="./api-dashboard.html#allocating-credit">API Dashboard</a> (requires $ Credit, which Pro users receive monthly).</p><div class="tip custom-block"><p class="custom-block-title">Credit purchases</p><p>API credit purchases are not live yet. The &quot;Get credits&quot; button opens an informational donation prompt — it doesn&#39;t process a purchase.</p></div><h2 id="weather" tabindex="-1">Weather <a class="header-anchor" href="#weather" aria-label="Permalink to &quot;Weather&quot;">​</a></h2><h3 id="why-is-my-accuracy-low" tabindex="-1">Why is my accuracy &quot;Low&quot;? <a class="header-anchor" href="#why-is-my-accuracy-low" aria-label="Permalink to &quot;Why is my accuracy &quot;Low&quot;?&quot;">​</a></h3><p>For BOM (Australia) data, accuracy is based on distance to the nearest reporting station: <strong>Low</strong> means the nearest station is more than 50 km away. The reading is still valid, just less local. See <a href="./how-it-works.html#accuracy-score">How It Works → Accuracy score</a>.</p><h3 id="can-i-use-my-own-weather-source" tabindex="-1">Can I use my own weather source? <a class="header-anchor" href="#can-i-use-my-own-weather-source" aria-label="Permalink to &quot;Can I use my own weather source?&quot;">​</a></h3><p>Yes — Pro users can add custom HTTPS weather sources. See <a href="./custom-weather-sources.html">Custom Weather Sources</a>.</p><h3 id="the-weather-looks-wrong" tabindex="-1">The weather looks wrong <a class="header-anchor" href="#the-weather-looks-wrong" aria-label="Permalink to &quot;The weather looks wrong&quot;">​</a></h3><p>Sky Style aggregates multiple sources and averages them. If a source returns bad data, it can skew the average. Pro users can use the <strong>source picker</strong> to choose a specific built-in source, or add a <a href="./custom-weather-sources.html">custom source</a> they trust.</p><h2 id="app-behaviour" tabindex="-1">App behaviour <a class="header-anchor" href="#app-behaviour" aria-label="Permalink to &quot;App behaviour&quot;">​</a></h2><h3 id="my-settings-didn-t-save" tabindex="-1">My settings didn&#39;t save <a class="header-anchor" href="#my-settings-didn-t-save" aria-label="Permalink to &quot;My settings didn&#39;t save&quot;">​</a></h3><p>Most preferences are stored in your browser&#39;s <code>localStorage</code> (keys prefixed with <code>skystyle_</code>). If they&#39;re not persisting:</p><ol><li>Make sure you clicked <strong>Save</strong> in Settings.</li><li>Check that your browser isn&#39;t blocking <code>localStorage</code> (private/incognito mode, or strict privacy settings).</li><li>Clearing site data will reset local preferences — you&#39;ll need to reconfigure them.</li></ol><h3 id="the-dashboard-tour-keeps-appearing" tabindex="-1">The dashboard tour keeps appearing <a class="header-anchor" href="#the-dashboard-tour-keeps-appearing" aria-label="Permalink to &quot;The dashboard tour keeps appearing&quot;">​</a></h3><p>The tour shows once per browser (tracked by <code>skystyle_tutorial_seen_&lt;id&gt;</code>). If it keeps reappearing, your browser may be clearing <code>localStorage</code> on exit. You can dismiss it with <strong>Skip</strong>, or replay it anytime from <a href="./settings.html#tutorials">Settings → Tutorials</a>.</p><h3 id="dark-mode-isn-t-working" tabindex="-1">Dark mode isn&#39;t working <a class="header-anchor" href="#dark-mode-isn-t-working" aria-label="Permalink to &quot;Dark mode isn&#39;t working&quot;">​</a></h3><p>Theme is controlled in <a href="./settings.html#appearance">Settings → Appearance</a>: system, light, or dark. &quot;System&quot; follows your OS preference — if your OS is in light mode, selecting &quot;system&quot; won&#39;t appear dark. Choose &quot;dark&quot; explicitly to force it.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><ul><li>Browse the full <a href="./web-app.html">Web App Guide</a> for detailed references.</li><li>Send a message from the <a href="./account-and-support.html#feedback">Feedback</a> page — every message is read personally.</li><li>Check the <a href="https://status.coolmanyt.com/" target="_blank" rel="noreferrer">COOLman service status page</a> for outages.</li></ul>',50)])])}const p=a(s,[["render",i]]);export{m as __pageData,p as default};
